\coordinate (A) at (0,0); \coordinate (B) at (5.5,0); \coordinate (C) at (8.5,4); \coordinate (D) at (3,4); \coordinate (H) at (4.5,0); \coordinate (P) at (4.5,4);
\draw[geometry] (A)--(B)--(C)--(D)--cycle;
\draw[guide,dashed] (P)--(H);
\foreach \U/\V in {A/B,D/C} {\draw[parallel] ($(\U)!0.40!(\V)$)--($(\U)!0.49!(\V)$); \draw[parallel] ($(\U)!0.49!(\V)$)--($(\U)!0.58!(\V)$);}
