\usetikzlibrary{calc,arrows.meta}
\begin{tikzpicture}[x=0.25cm,y=0.25cm,draw=black,text=black,line cap=round,line join=round,font=\fontsize{10}{12}\selectfont,geometry/.style={line width=0.8pt},guide/.style={line width=0.4pt},parallel/.style={line width=0.4pt,-{Stealth[length=1.5mm,width=1.2mm]}}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\pgfmathsetmacro{\shear}{sqrt(9.9*9.9-9.8*9.8)}
\coordinate (A) at (0,0); \coordinate (B) at (4.16,3.12);
\coordinate (D) at ({-0.8*\shear+0.6*9.8},{-0.6*\shear-0.8*9.8});
\coordinate (C) at ($(B)+(D)-(A)$);
\coordinate (P) at ({0.8*(5.2-\shear)},{0.6*(5.2-\shear)});
\draw[geometry] (A)--(B)--(C)--(D)--cycle;
\draw[guide,dashed] (P)--(C);
\foreach \U/\V in {B/A,C/D} {\draw[parallel] ($(\U)!0.42!(\V)$)--($(\U)!0.58!(\V)$);}
\foreach \U/\V in {A/D,B/C} {\draw[parallel] ($(\U)!0.42!(\V)$)--($(\U)!0.49!(\V)$); \draw[parallel] ($(\U)!0.49!(\V)$)--($(\U)!0.56!(\V)$);}
\coordinate (r1) at ($(P)!1.5mm!(A)$); \coordinate (r2) at ($(P)!1.5mm!(C)$); \draw[guide] (r1)--($(r1)+(r2)-(P)$)--(r2);
\path (P)--(C) node[midway,left=1mm] {$9.8\,\mathrm{m}$};
\path (A)--(D) node[midway,left=1mm] {$9.9\,\mathrm{m}$};
\path (D)--(C) node[midway,below right=1mm] {$5.2\,\mathrm{m}$};
\end{tikzpicture}
